// Care panel for Pet — the pet-raising UI migrated from PetClaw's care chapter.
// Right-click the pet to open near the character. Tabbed layout:
// status+interactions / inventory / shop / settings. Fixed light palette so
// it reads the same under any DSH theme.

import { useCallback, useEffect, useRef, useState, type FC } from 'react'
import type { MiniEngine } from './game/mini-engine.ts'
import type { ChatModel } from './PetChatBox.tsx'
import type { PetProfile, LineKey } from './custom-pets.ts'
import { LINE_KEYS, LINE_META } from './custom-pets.ts'
import {
  claimLogReward, claimWeekReward, getWitnessDay, getWitnessWeek, getWeekLog,
  recordCare, saveLogText, saveWeekLogText,
} from './game/witness-log.ts'
import { memoryTexts, type PetMemory } from './memory.ts'
import type { WorkspaceView } from './workspace.ts'
import { PixelIcon } from './pixel-icons.tsx'

interface Props {
  engine: MiniEngine
  anchor: { x: number; y: number } // pet screen position (panel opens beside it)
  petName: string // active companion name (header + switch button)
  chatModel: ChatModel | null // LLM used by the side chat box
  onChatModelChange: (model: ChatModel | null) => void // persist a new choice
  profile: PetProfile // active companion's persona + event lines
  onProfileChange: (patch: Partial<PetProfile>) => void // persist an edit
  onGeneratePet: (description: string) => Promise<{ ok: boolean; name?: string; error?: string }> // LLM sprite generation (spends coins)
  /** How many custom companions exist (0 → first generate is free). */
  customCount: number
  onImportPet: (text: string) => { ok: boolean; name?: string; error?: string } // share-file import (free)
  onPetSay: (text: string) => void // speak through the pet's bubble (wrapped)
  onSpeakPool: (key: LineKey) => void // fire a pool-keyed speech event through the pet's bubble
  onBurst: (opts?: { count?: number; color?: string }) => void // fire a particle burst at the pet's position
  /** Open the 45s runner mini-game (double-click on the pet does the same). */
  onPlayRunner: () => void
  onSwitchPet: () => void // reopen the companion picker
  memories: PetMemory[] // the pet's stored memories about the user
  onRemoveMemory: (id: string) => void // drop one memory
  autoMemory: boolean // automatic memory extraction enabled
  /** Vine-climb overlay for high platforms (default off: covers text). */
  vineClimb: boolean
  onVineClimbChange: (on: boolean) => void
  onAutoMemoryChange: (on: boolean) => void // persist the toggle
  workspace: WorkspaceView // host session list view (empty on old hosts)
  onClose: () => void
}

/** Provider+model list served by the plugin's node half. */
interface ModelListEntry {
  id: string
  name: string
  models: Array<{ id: string; name: string }>
  /** Set when listing this provider's models failed; the rest stay usable. */
  error?: string
}

